<script setup lang="ts">
import { ArrowUpRight, ArrowRight, BookOpen, AudioLines, Check, ChevronRight, CircleHelp, ClipboardCheck, Clock3, Download, GraduationCap, LayoutDashboard, Leaf, MessageCircle, PenLine, RotateCcw, Settings2, Sparkles, Target, TrendingUp, X } from 'lucide-vue-next'
import { exercises } from '~/data/exercises'
import { levels, type Skill } from '~/utils/practice'

const { language, level, progress, storageError, ready, session, index, selected, response, checklist, checked, finished, pool, current, scopedAttempts, accuracy, unseen, sessionScore, wordCount, start, submit, next, clearProgress, downloadProgress } = usePractice()
const view = ref<'home' | 'practice' | 'progress' | 'guide'>('home')
const confirmReset = ref(false)
const langName = computed(() => language.value === 'ca' ? 'Catalán' : 'Inglés')
const skills = [
  { id: 'grammar' as Skill, name: 'Gramática y vocabulario', short: 'Gramática', description: 'Encuentra la palabra que encaja. Entiende el porqué.', icon: BookOpen, color: 'mint', time: '3 min' },
  { id: 'reading' as Skill, name: 'Comprensión lectora', short: 'Lectura', description: 'Lee con intención. Conecta ideas y descubre matices.', icon: ClipboardCheck, color: 'peach', time: '5 min' },
  { id: 'writing' as Skill, name: 'Expresión escrita', short: 'Escritura', description: 'Ordena tus ideas y dales tu propia voz.', icon: PenLine, color: 'lilac', time: '15–25 min' },
  { id: 'speaking' as Skill, name: 'Expresión oral', short: 'Oral', description: 'Gana soltura hablando de situaciones reales.', icon: MessageCircle, color: 'sand', time: '5–10 min' },
]
const currentSkill = computed(() => skills.find(s => s.id === current.value?.skill))
const completedIds = computed(() => new Set(scopedAttempts.value.map(a => a.exerciseId)))
const coverage = computed(() => Math.round(completedIds.value.size / pool.value.length * 100))
const recentAttempts = computed(() => [...scopedAttempts.value].reverse().slice(0, 20))
const canSubmit = computed(() => current.value?.options ? selected.value !== null : checklist.value.length > 0 && (current.value?.skill !== 'writing' || !!response.value.trim()))
const completedDays = computed(() => new Set(scopedAttempts.value.map(a => new Date(a.date).toLocaleDateString('es-ES'))).size)
const heading = ref<HTMLElement | null>(null)

function focusHeading() { nextTick(() => heading.value?.focus()) }
function begin(skill: Skill | 'mixed') { start(skill); view.value = 'practice'; focusHeading() }
function advance() { next(); focusHeading() }
function changeScope() { view.value = 'home'; session.value = []; confirmReset.value = false }
function findExercise(id: string) { return exercises.find(q => q.id === id) }
function formatDate(date: number) { return new Date(date).toLocaleString('es-ES', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) }
</script>

<template>
  <div class="app-shell">
    <a class="skip-link" href="#main-content">Saltar al contenido</a>
    <aside class="sidebar">
      <a href="#" class="brand" aria-label="Lang School, inicio" @click.prevent="view = 'home'"><span class="brand-mark"><GraduationCap :size="24" /></span><span>lang<span class="font-normal">school</span><span class="brand-dot">.</span></span></a>
      <div class="workspace-label">TU ESPACIO DE APRENDIZAJE</div>
      <nav aria-label="Principal" class="main-nav">
        <button :aria-current="view === 'home' ? 'page' : undefined" :class="{ active: view === 'home' }" @click="view = 'home'"><LayoutDashboard :size="19" /> Mi aprendizaje</button>
        <button :aria-current="view === 'practice' ? 'page' : undefined" :class="{ active: view === 'practice' }" @click="session.length ? (view = 'practice') : begin('mixed')"><BookOpen :size="19" /> Practicar <span class="nav-dot" /></button>
        <button :aria-current="view === 'progress' ? 'page' : undefined" :class="{ active: view === 'progress' }" @click="view = 'progress'"><TrendingUp :size="19" /> Mi progreso</button>
      </nav>
      <div class="sidebar-goal"><span class="eyebrow">PASO A PASO</span><div class="goal-drawing"><Leaf :size="40" :stroke-width="1.2" /><span>↗</span></div><h3>Un poco cada día.<br>Mucho más lejos.</h3><p>Tu próxima meta empieza con unos minutos de práctica.</p><span class="goal-tag"><Target :size="13" /> Objetivo {{ level }}</span></div>
      <button class="guide-link" :class="{ 'text-green-900': view === 'guide' }" @click="view = 'guide'"><CircleHelp :size="18" /> Guía y recursos <ArrowUpRight :size="16" /></button>
      <div class="local-profile"><span class="avatar">T</span><div><strong>Tu espacio personal</strong><small>Progreso en este navegador</small></div><span class="status-dot" /></div>
    </aside>

    <div class="main-shell">
      <header class="topbar"><div class="breadcrumb">Mi espacio <ChevronRight :size="14" /><strong>{{ view === 'home' ? 'Mi aprendizaje' : view === 'practice' ? 'Práctica' : view === 'progress' ? 'Mi progreso' : 'Guía y recursos' }}</strong></div><span class="private-badge"><span /> A tu ritmo, sin presión</span></header>
      <main id="main-content" tabindex="-1">
        <div v-if="storageError" role="alert" class="notice mb-6">{{ storageError }}</div>
        <div class="page-title"><div><p class="eyebrow">{{ view === 'home' ? 'TU CUADERNO DE IDIOMAS' : view === 'practice' ? 'EL PROGRESO SE PRACTICA' : view === 'progress' ? 'CADA PASO CUENTA' : 'PREPARA TU CAMINO' }}</p><h1 ref="heading" tabindex="-1">{{ view === 'home' ? 'Haz sitio a una nueva conversación.' : view === 'practice' ? 'Concéntrate en una cosa.' : view === 'progress' ? 'Mira cuánto has avanzado.' : 'Una buena base para empezar.' }}</h1><p class="subtitle">{{ view === 'home' ? 'Catalán e inglés. Un ejercicio, una idea nueva, un paso adelante.' : view === 'practice' ? 'Tómate tu tiempo. Equivocarse también es aprender.' : view === 'progress' ? 'Tu recorrido de práctica, sin convertirlo en una nota de examen.' : 'Práctica independiente con la vista puesta en EOI y Govern Balear.' }}</p></div><span class="edition">PRIMERA EDICIÓN <span>✦</span></span></div>

        <section class="scope-bar" aria-label="Configurar práctica"><div class="language-switch" role="group" aria-label="Idioma"><button :aria-pressed="language === 'ca'" :class="{ chosen: language === 'ca' }" @click="language = 'ca'; changeScope()"><span class="language-symbol ca-symbol">≋</span> Catalán</button><button :aria-pressed="language === 'en'" :class="{ chosen: language === 'en' }" @click="language = 'en'; changeScope()"><span class="language-symbol">En</span> Inglés</button></div><div class="level-picker"><label for="level"><Settings2 :size="15" /> Tu nivel</label><select id="level" v-model="level" @change="changeScope()"><option v-for="item in levels" :key="item" :value="item">{{ item }}{{ item === 'B2' ? ' · Intermedio alto' : '' }}</option></select></div><span class="scope-note">{{ language === 'ca' ? 'Referencia: EOI / Govern Balear' : 'Referencia: EOI Illes Balears' }}</span></section>

        <template v-if="view === 'home'">
          <div class="home-grid">
            <section class="hero-card"><div class="hero-copy"><span class="hero-pill"><Sparkles :size="13" /> LA PRÁCTICA DE HOY</span><h2>Un poco de práctica.<br><em>Un mundo que contar.</em></h2><p>Activa lo que sabes con una sesión de gramática y lectura de {{ langName.toLowerCase() }} {{ level }}.</p><button class="primary-button" :disabled="!ready" @click="begin('mixed')">Empezar práctica <ArrowRight :size="18" /></button><span class="hero-detail"><Clock3 :size="14" /> 4 ejercicios · a tu ritmo</span></div><div class="hero-art" aria-hidden="true"><span class="orbit orbit-one" /><span class="orbit orbit-two" /><span class="art-star">✳</span><div class="word-card word-card-back">{{ language === 'ca' ? 'Bon dia' : 'Hello' }}<span>Un mundo por descubrir.</span><span class="card-line" /><span class="card-line short" /></div><div class="word-card word-card-front">{{ language === 'ca' ? 'Parlem?' : 'Let’s talk' }}<span>{{ language === 'ca' ? 'Una passa més.' : 'One step closer.' }}</span><div class="word-card-bottom"><span class="mini-bars"><i /><i /><i /><i /><i /></span><span class="round-arrow">↗</span></div></div><span class="art-dot" /></div></section>
            <section class="today-card"><div class="flex items-center justify-between"><h3>Tu recorrido</h3><span class="icon-tile small mint"><TrendingUp :size="18" /></span></div><p class="muted mt-2">{{ langName }} · {{ level }}</p><div class="journey-number">{{ completedIds.size }}<span> / {{ pool.length }}</span></div><p class="text-sm muted">ejercicios diferentes completados</p><div class="progress-track mt-5" role="progressbar" aria-label="Ejercicios completados" :aria-valuenow="coverage" :aria-valuemin="0" :aria-valuemax="100"><span :style="{ width: `${coverage}%` }" /></div><div class="flex justify-between text-xs muted mt-2"><span>Tu banco inicial</span><span>{{ coverage }}%</span></div><div class="journey-footer"><span class="tiny-leaf"><Leaf :size="16" /></span><p>{{ scopedAttempts.length ? 'La constancia deja huella. Sigue así.' : 'Todo empieza con el primer ejercicio.' }}</p></div></section>
          </div>
          <div class="section-heading"><div><h2>¿Qué te apetece practicar?</h2><p>Elige una destreza y dedica un momento a mejorarla.</p></div><span class="subtle-tag">{{ langName }} <span>·</span> {{ level }}</span></div>
          <div class="skill-grid"><button v-for="skill in skills" :key="skill.id" class="skill-card" :disabled="!ready" @click="begin(skill.id)"><div class="flex justify-between items-start"><span class="icon-tile" :class="skill.color"><component :is="skill.icon" :size="23" :stroke-width="1.6" /></span><ArrowUpRight :size="18" class="card-arrow" /></div><h3>{{ skill.name }}</h3><p>{{ skill.description }}</p><div class="skill-footer"><span><Clock3 :size="13" /> {{ skill.time }}</span><span>{{ skill.id === 'writing' || skill.id === 'speaking' ? 'Autoevaluación' : 'Con explicación' }}</span></div></button></div>
          <section class="bottom-banner"><span class="icon-tile mint"><Sparkles :size="22" /></span><div><h3>Más variedad. Menos «esto ya lo he visto».</h3><p>{{ unseen }} de {{ pool.length }} ejercicios sin ver en {{ langName.toLowerCase() }} {{ level }}. Priorizamos los nuevos; al agotar el banco, recuperamos los menos recientes.</p></div><button class="text-button" @click="view = 'guide'">Cómo funciona <ArrowRight :size="16" /></button></section>
          <p class="content-note">Banco inicial de {{ exercises.length }} actividades originales · Niveles orientativos A1–C2 · Escucha y mediación, pendientes.</p>
        </template>

        <template v-else-if="view === 'practice'">
          <section v-if="finished" class="exercise-panel result-panel" aria-live="polite"><span class="result-icon"><Check :size="32" /></span><p class="eyebrow mt-5">UN PASO MÁS</p><h2>Sesión completada.</h2><p v-if="sessionScore.length" class="result-score">{{ sessionScore.filter(Boolean).length }} <span>/ {{ sessionScore.length }} aciertos</span></p><p v-else class="mt-4 muted">Has dedicado un momento a expresarte. Tu autoevaluación queda registrada como práctica, sin nota automática.</p><p class="muted mt-4">{{ unseen ? `Te quedan ${unseen} actividades sin ver en este idioma y nivel.` : 'Has visto todo el banco de este nivel. Las próximas sesiones recuperarán las actividades menos recientes.' }}</p><div class="flex flex-wrap justify-center gap-3 mt-7"><button class="primary-button" @click="begin('mixed')">Practicar gramática y lectura <ArrowRight :size="17" /></button><button class="secondary-button" @click="view = 'progress'">Ver mi progreso</button></div></section>
          <section v-else-if="current" class="exercise-panel"><div class="exercise-meta"><span class="subtle-tag">{{ currentSkill?.name }} · {{ level }}</span><span>{{ index + 1 }} de {{ session.length }}</span></div><div class="progress-track my-6"><span :style="{ width: `${(index + 1) / session.length * 100}%` }" /></div><div :lang="language"><h2>{{ current.title }}</h2><blockquote v-if="current.passage" class="passage">{{ current.passage }}</blockquote><p class="question">{{ current.prompt }}</p><fieldset v-if="current.options" :disabled="checked" class="answer-options"><legend class="sr-only">Elige una respuesta</legend><label v-for="(option, i) in current.options" :key="i" class="answer-option" :class="{ selected: selected === i, correct: checked && current.answer === i, wrong: checked && selected === i && current.answer !== i }"><input v-model="selected" type="radio" name="answer" :value="i" /><span class="answer-letter">{{ String.fromCharCode(65 + i) }}</span><span>{{ option }}</span><Check v-if="checked && current.answer === i" :size="19" class="ml-auto" /></label></fieldset></div>
            <div v-if="!current.options" class="open-response"><p v-if="current.words" class="muted text-sm mb-3">Objetivo orientativo: {{ current.words[0] }}–{{ current.words[1] }} palabras. No es un límite obligatorio.</p><p v-else class="notice mb-4">Practica en voz alta durante 2–3 minutos o con otra persona. Esta versión no graba ni evalúa tu voz.</p><label for="response" class="field-label">{{ current.skill === 'writing' ? 'Tu texto' : 'Notas de tu práctica (opcional)' }}</label><textarea id="response" v-model="response" :lang="language" :disabled="checked" :rows="current.skill === 'writing' ? 9 : 4" :placeholder="language === 'ca' ? 'Comença aquí…' : 'Start here…'" /><div class="text-right text-xs muted mt-2">{{ wordCount }} palabras</div><fieldset :disabled="checked" class="self-check"><legend>Reflexiona sobre tu práctica</legend><p class="muted text-sm mb-3">Marca los puntos que has trabajado. Esto no genera una calificación.</p><label v-for="item in current.checklist" :key="item"><input v-model="checklist" type="checkbox" :value="item" /><span>{{ item }}</span></label></fieldset></div>
            <div v-if="checked" role="status" class="feedback" :class="{ 'feedback-error': current.options && selected !== current.answer }"><strong>{{ current.options ? selected === current.answer ? '¡Bien hecho! Esta es la respuesta.' : 'Un buen momento para aprender.' : 'Práctica guardada. Ahora revisa tu trabajo.' }}</strong><p>{{ current.explanation || 'Compara tu respuesta con la consigna. Para una valoración fiable de tu expresión, consulta a un docente o evaluador.' }}</p></div><div class="exercise-actions"><button class="text-button" @click="view = 'home'">Volver al inicio</button><button v-if="!checked" class="primary-button" :disabled="!canSubmit" @click="submit">{{ current.options ? 'Comprobar respuesta' : 'Guardar práctica' }} <Check :size="17" /></button><button v-else class="primary-button" @click="advance">{{ index + 1 === session.length ? 'Ver resultado' : 'Siguiente ejercicio' }} <ArrowRight :size="17" /></button></div>
          </section>
          <section v-else class="exercise-panel"><h2>Elige tu primera sesión.</h2><button class="primary-button mt-5" :disabled="!ready" @click="begin('mixed')">Empezar práctica <ArrowRight :size="17" /></button></section>
          <p class="content-note">Actividades de práctica independientes. No son una simulación ni una calificación oficial.</p>
        </template>

        <template v-else-if="view === 'progress'">
          <div class="stats-grid"><section class="stat-card"><span>Prácticas completadas</span><strong>{{ scopedAttempts.length }}</strong><small>{{ completedIds.size }} ejercicios distintos</small></section><section class="stat-card"><span>Aciertos en preguntas corregibles</span><strong>{{ accuracy === null ? '—' : `${accuracy}%` }}</strong><small>Escritura y oral no se puntúan</small></section><section class="stat-card"><span>Días con práctica</span><strong>{{ completedDays }}</strong><small>En {{ langName.toLowerCase() }} {{ level }}</small></section></div>
          <section class="exercise-panel mt-6"><div class="section-heading !mt-0"><div><h2>Tu actividad reciente</h2><p>Hasta 20 prácticas de {{ langName.toLowerCase() }} {{ level }}.</p></div><button class="secondary-button" :disabled="!progress.attempts.length" @click="downloadProgress"><Download :size="16" /> Exportar todo</button></div><div v-if="!recentAttempts.length" class="empty-state"><span class="icon-tile mint"><BookOpen :size="26" /></span><h3>Tu historia empieza aquí.</h3><p>Completa un ejercicio y aparecerá en este espacio.</p><button class="primary-button mt-5" @click="begin('mixed')">Hacer mi primera práctica <ArrowRight :size="16" /></button></div><ol v-else class="history-list"><li v-for="attempt in recentAttempts" :key="attempt.id"><span class="history-icon" :class="{ missed: attempt.correct === false }"><Check v-if="attempt.correct === true" :size="17" /><PenLine v-else-if="attempt.correct === null" :size="17" /><RotateCcw v-else :size="16" /></span><div><strong>{{ findExercise(attempt.exerciseId)?.title || 'Ejercicio' }}</strong><small>{{ formatDate(attempt.date) }} · {{ attempt.correct === null ? 'Autoevaluación, sin nota' : attempt.correct ? 'Respuesta correcta' : 'Respuesta por revisar' }}</small><details><summary>Ver mi respuesta</summary><p>{{ attempt.answer || 'Práctica oral sin notas.' }}</p><p v-if="findExercise(attempt.exerciseId)?.explanation" class="muted">{{ findExercise(attempt.exerciseId)?.explanation }}</p></details></div></li></ol></section>
          <div class="data-controls"><p>Los textos y el historial se guardan solo en este navegador. Exporta una copia antes de borrar sus datos.</p><button v-if="!confirmReset" class="text-button" @click="confirmReset = true">Borrar progreso</button><div v-else class="flex gap-3 items-center flex-wrap"><strong>¿Borrar todo el historial de ambos idiomas?</strong><button class="danger-button" @click="clearProgress(); confirmReset = false">Sí, borrar todo</button><button class="text-button" @click="confirmReset = false">Cancelar</button></div></div>
        </template>

        <template v-else>
          <div class="guide-grid"><section class="exercise-panel"><span class="icon-tile mint"><Target :size="24" /></span><h2 class="mt-5">Una meta, dos referencias.</h2><p class="muted mt-4">Prepararemos el recorrido B2 tomando como referencia la EOI de las Illes Balears y, para catalán, los certificados del Govern Balear. Sus estructuras son distintas: esta edición trabaja destrezas comunes y todavía no reproduce sus exámenes.</p><a class="resource-link" href="https://www.caib.es/sites/eoibalears/ca/nivell_intermedi%20b2-83980/" target="_blank" rel="noopener noreferrer">Modelos B2 de EOI Balears <ArrowUpRight :size="17" /></a><a class="resource-link" href="https://www.caib.es/webgoib/-/certificat-de-nivell-b2" target="_blank" rel="noopener noreferrer">Certificado B2 de catalán · Govern <ArrowUpRight :size="17" /></a><p class="text-xs muted mt-4">Consulta siempre las instrucciones de tu convocatoria. Lang School es un proyecto independiente, sin afiliación institucional.</p></section><section class="exercise-panel"><span class="icon-tile lilac"><Sparkles :size="24" /></span><h2 class="mt-5">Cómo evitamos repetir.</h2><p class="muted mt-4">Primero aparecen las actividades que no has visto. Al agotar una destreza, vuelven las que viste hace más tiempo. Cambiar el orden de las respuestas no cuenta como un ejercicio nuevo.</p><p class="muted mt-4">El banco inicial tiene {{ exercises.length }} actividades: 6 por idioma y nivel. Es una base pequeña para comprobar el recorrido, con niveles orientativos pendientes de revisión docente.</p><p class="muted mt-4">El historial es local a este navegador. Todavía no se sincroniza entre dispositivos.</p></section></div>
          <section class="bottom-banner"><span class="icon-tile sand"><AudioLines :size="24" /></span><div><h3>El siguiente capítulo</h3><p>Ampliar el banco revisado, incorporar audios y mediación EOI, añadir simulacros por convocatoria y guardar el progreso en una cuenta.</p></div></section>
        </template>

        <footer><button class="text-button" @click="view = 'guide'; focusHeading()">Guía y recursos <ArrowUpRight :size="14" /></button><span>langschool<span class="text-green-800">.</span> <span class="footer-divider">/</span> Aprende para entender. Practica para conectar.</span><span>Hecho para avanzar, a tu ritmo <Leaf :size="13" /></span></footer>
      </main>
    </div>
  </div>
</template>
